#!/usr/bin/env node
const fs = require('fs');
const path = require('path');

// Keep in sync with src/tokens/breakpoints.js (verified by breakpoints.test.js)
const BREAKPOINTS = {
    xs: 0,
    sm: 576,
    md: 768,
    lg: 992,
    xl: 1200,
    xxl: 1600
};
const MOBILE_BREAKPOINT = BREAKPOINTS.md;

const outDir = path.join(__dirname, '../scss');
const outFile = path.join(outDir, '_tokens.scss');

const lines = [
    '// Auto-generated by scripts/generate-scss-tokens.js — do not edit manually',
    `$breakpoint-mobile: ${MOBILE_BREAKPOINT}px;`,
    ''
];

Object.entries(BREAKPOINTS).forEach(([key, value]) => {
    lines.push(`$breakpoint-${key}: ${value}px;`);
});

lines.push(
    '',
    '$breakpoints: (',
    ...Object.keys(BREAKPOINTS).map((key, index, arr) => {
        const suffix = index < arr.length - 1 ? ',' : '';
        return `  ${key}: $breakpoint-${key}${suffix}`;
    }),
    ');',
    ''
);

fs.mkdirSync(outDir, {recursive: true});
fs.writeFileSync(outFile, lines.join('\n'));
console.log('Wrote', outFile);
